import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { useSelector } from "react-redux"; // ← Added for proper user check
import api from "../../api/axios";

const TicketDetail = () => {
  const { id } = useParams();
  const { user } = useSelector((state) => state.auth); // ← Get user from Redux
  const isAdmin = user?.is_staff || false; // ← Safe check

  const [ticket, setTicket] = useState(null);
  const [users, setUsers] = useState([]); // For assigned_to dropdown
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isEditing, setIsEditing] = useState(false);

  // Editable form state
  const [editForm, setEditForm] = useState({
    status: "",
    assigned_to: "",
    confidential_notes: "",
  });

  useEffect(() => {
    const fetchTicket = async () => {
      try {
        setLoading(true);
        const res = await api.get(`tickets/${id}/`);
        setTicket(res.data);

        // Initialize form
        setEditForm({
          status: res.data.status || "OPEN",
          assigned_to: res.data.assigned_to || "",
          confidential_notes: res.data.confidential_notes || "",
        });
      } catch (err) {
        console.error(err);
        setError("Failed to load ticket details.");
      } finally {
        setLoading(false);
      }
    };

    fetchTicket();
  }, [id]);

  // Fetch users only for admin (to assign tickets)
  useEffect(() => {
    if (isAdmin) {
      const fetchUsers = async () => {
        try {
          // Adjust this endpoint if your backend has a different one for listing users
          const res = await api.get("/auth/users/"); 
          setUsers(res.data);
        } catch (err) {
          console.warn("Could not load users for assignment:", err);
        }
      };
      fetchUsers();
    }
  }, [isAdmin]);

  const handleSave = async () => {
    try {
      const updateData = {};

      if (editForm.status !== ticket.status) updateData.status = editForm.status;
      if (editForm.assigned_to !== ticket.assigned_to)
        updateData.assigned_to = editForm.assigned_to || null;
      if (editForm.confidential_notes !== ticket.confidential_notes)
        updateData.confidential_notes = editForm.confidential_notes;

      if (Object.keys(updateData).length === 0) {
        setIsEditing(false);
        return;
      }

      const res = await api.patch(`tickets/${id}/`, updateData);
      setTicket(res.data);
      setIsEditing(false);
      alert("Ticket updated successfully!");
    } catch (err) {
      console.error("Update failed:", err);
      alert("Failed to update ticket.");
    }
  };

  const updateStatus = async (newStatus) => {
    try {
      const res = await api.patch(`tickets/${id}/`, { status: newStatus });
      setTicket(res.data);
    } catch (err) {
      console.error("Status update failed:", err);
    }
  };

  if (loading) return <div style={styles.loading}>Loading ticket details...</div>;
  if (error) return <div style={styles.error}>{error}</div>;
  if (!ticket) return null;

  const getPriorityBadge = (priority) => {
    const p = priority?.toUpperCase() || "";
    if (p === "HIGH") return { bg: "#ff4d4f", text: "High" };
    if (p === "MEDIUM") return { bg: "#faad14", text: "Medium" };
    if (p === "LOW") return { bg: "#52c41a", text: "Low" };
    return { bg: "#d9d9d9", text: priority || "N/A" };
  };

  const getStatusBadge = (status) => {
    const s = status?.toUpperCase() || "";
    switch (s) {
      case "OPEN": return { bg: "#1890ff", text: "Open" };
      case "IN_PROGRESS": return { bg: "#faad14", text: "In Progress" };
      case "RESOLVED": return { bg: "#52c41a", text: "Resolved" };
      case "PARTIALLY_CLOSED": return { bg: "#9254de", text: "Partially Closed" };
      default: return { bg: "#d9d9d9", text: status || "N/A" };
    }
  };

  const priorityBadge = getPriorityBadge(ticket.priority);
  const statusBadge = getStatusBadge(ticket.status);

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        {/* Header */}
        <div style={styles.header}>
          <h3 style={styles.title}>Ticket #{id} - {ticket.title}</h3>
          <div style={styles.badges}>
            <span style={{ ...styles.badge, background: priorityBadge.bg }}>
              {priorityBadge.text}
            </span>
            <span style={{ ...styles.badge, background: statusBadge.bg }}>
              {statusBadge.text}
            </span>
          </div>
        </div>

        {/* Details */}
        <div style={styles.details}>
          <p style={styles.description}>{ticket.description}</p>

          {ticket.attachments?.length > 0 ? (
            <div style={styles.attachments}>
              <strong>Attachments:</strong>
              <ul style={styles.attachmentList}>
                {ticket.attachments.map((att, idx) => (
                  <li key={idx}>
                    <a href={att.file || att} target="_blank" rel="noopener noreferrer">
                      {att.name || `Attachment ${idx + 1}`}
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          ) : (
            <p style={styles.noAttachment}>No attachments</p>
          )}

          {/* Admin-only Editable Section */}
          {isAdmin && (
            <>
              <hr style={styles.hr} />
              <div style={styles.adminSection}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <h5 style={styles.adminTitle}>Admin Controls</h5>
                  {!isEditing ? (
                    <button onClick={() => setIsEditing(true)} style={styles.editButton}>
                      Edit Ticket
                    </button>
                  ) : (
                    <div style={{ display: "flex", gap: "10px" }}>
                      <button onClick={handleSave} style={styles.saveButton}>Save</button>
                      <button onClick={() => setIsEditing(false)} style={styles.cancelButton}>Cancel</button>
                    </div>
                  )}
                </div>

                {/* Status */}
                <div style={styles.field}>
                  <strong>Status:</strong>
                  {isEditing ? (
                    <select
                      value={editForm.status}
                      onChange={(e) => setEditForm({ ...editForm, status: e.target.value })}
                      style={styles.select}
                    >
                      <option value="OPEN">Open</option>
                      <option value="IN_PROGRESS">In Progress</option>
                      <option value="RESOLVED">Resolved</option>
                      <option value="PARTIALLY_CLOSED">Partially Closed</option>
                    </select>
                  ) : (
                    <span style={{ marginLeft: "10px", fontWeight: "600" }}>
                      {statusBadge.text}
                    </span>
                  )}
                </div>

                {/* Assigned To */}
                <div style={styles.field}>
                  <strong>Assigned To:</strong>
                  {isEditing ? (
                    <select
                      value={editForm.assigned_to}
                      onChange={(e) => setEditForm({ ...editForm, assigned_to: e.target.value })}
                      style={styles.select}
                    >
                      <option value="">Unassigned</option>
                      {users.map((u) => (
                        <option key={u.id} value={u.id}>
                          {u.email} (ID: {u.id})
                        </option>
                      ))}
                    </select>
                  ) : (
                    <span style={{ marginLeft: "10px" }}>
                      {ticket.assigned_to ? `User #${ticket.assigned_to}` : "Unassigned"}
                    </span>
                  )}
                </div>

                {/* Confidential Notes */}
                <div style={styles.field}>
                  <strong>Confidential Notes:</strong>
                  {isEditing ? (
                    <textarea
                      value={editForm.confidential_notes}
                      onChange={(e) => setEditForm({ ...editForm, confidential_notes: e.target.value })}
                      rows="4"
                      style={styles.textarea}
                      placeholder="These notes are encrypted and visible only to admins..."
                    />
                  ) : (
                    <p style={styles.notes}>
                      {ticket.confidential_notes || "No notes available"}
                    </p>
                  )}
                </div>

                {/* Quick Resolve Button (kept your original feature) */}
                {!isEditing && ticket.status !== "RESOLVED" && (
                  <button onClick={() => updateStatus("RESOLVED")} style={styles.resolveButton}>
                    Mark as Resolved
                  </button>
                )}
              </div>
            </>
          )}

          {/* Audit Log */}
          <hr style={styles.hr} />
          <h5 style={styles.auditTitle}>Audit Log</h5>
          {ticket.audit_logs?.length > 0 ? (
            <ul style={styles.auditList}>
              {ticket.audit_logs.map((log) => (
                <li key={log.id} style={styles.auditItem}>
                  <span style={styles.auditTime}>
                    {new Date(log.created_at || log.timestamp).toLocaleString()}
                  </span>
                  <span>{log.message}</span>
                </li>
              ))}
            </ul>
          ) : (
            <p style={styles.noLogs}>No audit logs available</p>
          )}
        </div>
      </div>
    </div>
  );
};

